    donor_reputation: float,
    recipient_reputation: float,
    donor_action: str,
    recipient_action: str,
    my_reputation: float
) -> float:
    # Norm: cooperate with good recipients is good, defect with bad recipients is good.
    # Recipient_action and my_reputation are not used.
    threshold = 0.0
    rate = 0.2
    if recipient_reputation > threshold:
        good = (donor_action == 'cooperate')
    elif recipient_reputation < -threshold:
        good = (donor_action == 'defect')
    else:
        good = None  # neutral

